"""Offline, standard-library HTML renderer. Navigation contract reused from g7-l08."""
from pathlib import Path
import html
import json
import sys

ROOT = Path(__file__).resolve().parent
def esc(value):
    return html.escape(str(value), quote=True)

def led(pattern, label):
    assert len(pattern) == 25 and set(pattern) <= {'0', '1'}
    cells = ''.join(f'<rect x="{15+(i%5)*32}" y="{15+(i//5)*32}" width="22" height="22" fill="{("#ff526c" if bit=="1" else "#314257")}"/>' for i,bit in enumerate(pattern))
    return f'<svg class="led" viewBox="0 0 180 180" role="img" aria-label="{esc(label)}; рядки {esc("; ".join(pattern[i:i+5] for i in range(0,25,5)))}" data-pattern="{pattern}"><rect width="180" height="180" rx="12" fill="#172b46"/>{cells}</svg>'

def flow():
    return '''<svg class="flowchart" viewBox="0 45 1000 210" role="img" aria-label="Подія: натиснуто A. Показати погляд вліво. Кінець обробника."><defs><marker id="arrowA" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto"><path d="M0 0L10 5L0 10" fill="#1c765c"/></marker></defs><g stroke="#1c765c" stroke-width="4" fill="none" marker-end="url(#arrowA)"><path d="M280 150H350"/><path d="M660 150H730"/></g><g stroke="#263b55" stroke-width="3" fill="#e3f7ef"><rect x="10" y="100" width="270" height="100" rx="50"/><path d="M385 85H695L660 215H350Z"/><rect x="735" y="100" width="255" height="100" rx="50"/></g><g text-anchor="middle" fill="#172b46" font-family="Segoe UI,Arial,sans-serif" font-size="29" font-weight="650"><text x="145" y="140">Подія:</text><text x="145" y="177">натиснуто A</text><text x="522" y="140">Показати</text><text x="522" y="177">погляд вліво</text><text x="862" y="140">Кінець</text><text x="862" y="177">обробника</text></g></svg>'''

def body(s, patterns):
    heading=f'<header><p class="eyebrow">{esc(s["stage"])}</p><h1>{esc(s["title"])}</h1><p class="subtitle">{esc(s.get("subtitle", ""))}</p></header>'
    kind=s['layout']
    if kind=='hero':
        content=f'<div class="hero-art">{led(patterns["A+B"], "Погляд прямо")}<p>A · B · A+B</p></div>'
    elif kind=='cards':
        content='<div class="cards-grid">'+''.join(f'<div class="panel"><b>{esc(a)}</b><p>{esc(b)}</p></div>' for a,b in s['items'])+'</div>'
    elif kind=='mapping':
        content='<div class="mapping-grid">'+''.join(f'<div><span class="keycap">{esc(k)}</span>{led(patterns[k],label)}<h2>{esc(label)}</h2></div>' for k,label in [('A','Вліво'),('B','Вправо'),('A+B','Прямо')])+'</div>'
    elif kind=='matrix':
        content=f'<div class="matrix-row">{led(patterns["A"],"Погляд вліво")}<div><p class="big-number">5 × 5 = 25</p><p>Рахуй рядки згори вниз,<br>стовпці — зліва направо.</p><p class="legend"><span>■</span> світиться · <i>■</i> вимкнено</p></div></div>'
    elif kind=='patterns':
        content='<div class="patterns-grid">'+''.join(f'<div><h2>{esc(k)} · {esc(label)}</h2>{led(patterns[k],label)}<pre class="bitrows">'+ '\n'.join(patterns[k][i:i+5] for i in range(0,25,5))+'</pre></div>' for k,label in [('A','вліво'),('B','вправо'),('A+B','прямо')])+'</div>'
    elif kind=='flow': content=flow()+'<div class="mobile-flow"><div>Подія: натиснуто A</div><span>↓</span><div>Показати погляд вліво</div><span>↓</span><div>Кінець обробника</div></div><p class="emphasis">Обробник завершився. Програма чекає нової події.</p>'
    elif kind=='pseudo':
        content='<div class="pseudo-list">'+''.join(f'<div><b>КОЛИ натиснуто {esc(k)}</b><span>ПОКАЗАТИ погляд {esc(label)}</span></div>' for k,label in [('A','вліво'),('B','вправо'),('A+B','прямо')])+'</div>'
    elif kind=='steps':
        content='<ol class="steps-list">'+''.join(f'<li><b>{i+1:02d}</b><span>{esc(t)}</span></li>' for i,t in enumerate(s['items']))+'</ol>'
    elif kind=='blocks':
        content='<div class="block-rows">'+''.join(f'<div><b>{esc(a)}</b><strong>{esc(b)}</strong><p>{esc(c)}</p></div>' for a,b,c in s['items'])+'</div>'
    elif kind=='build':
        content='<div class="build-row"><div class="makecode-block"><b>на кнопку <span>A ▾</span> натиснуто</b><div class="basic-block"><strong>показати світлодіоди</strong>'+led(patterns['A'],'Погляд вліво')+'</div></div><ol>'+''.join(f'<li>{esc(t)}</li>' for t in s['items'])+'</ol></div>'
    elif kind=='closing': content=''
    else: raise ValueError(kind)
    tail=f'<p class="callout">{esc(s["callout"])}</p>' if s.get('callout') else ''
    return heading+'<div class="slide-content">'+content+tail+'</div>'

